def cases():return json.loads(json.dumps(CASES))
@lru_cache(maxsize=1)
def _rows():return {r['case']['key']:r for r in json.loads(FIXTURE.read_text(encoding='utf-8'))['rows']}
def expected(case):return json.loads(json.dumps(_rows()[case['key']]['expected']))
def packed(value):
    if isinstance(value,dict):return {k:packed(v) for k,v in value.items()}
    if isinstance(value,list):return [packed(v) for v in value]
    return str(value) if isinstance(value,float) and not math.isfinite(value) else value
def production(case):
    from PyFLASH.stats_extra import fit_growth_curve
    p=case['parameters']
    try:
        answer=fit_growth_curve([np.nan if v is None else float(v) for v in p['x']],
            [np.nan if v is None else float(v) for v in p['y']],p.get('model','auto'))
    except (ValueError,RuntimeError) as error:
        return {'error_type':type(error).__name__}
    if set(answer)!={'model','params','r_squared','aic','n','predict','all_models'}:raise ValueError('Growth return schema differs')
    answer['predictions']=answer.pop('predict')(p['prediction_x']).tolist()
    return packed(answer)

def equal(a,b):
    if isinstance(a,dict):return isinstance(b,dict) and a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)
    if isinstance(a,list):return isinstance(b,list) and len(a)==len(b) and all(equal(x,y) for x,y in zip(a,b))
    if isinstance(a,(int,float)) and isinstance(b,(int,float)):return math.isclose(a,b,rel_tol=1e-9,abs_tol=1e-12)
    return a==b
def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:raise ValueError('Growth reference source changed')
    if cases()!=[r['case'] for r in fixture['rows']]:raise ValueError('Frozen growth definitions changed')
    for name,sha in fixture['source_manifest'].items():
        if hashlib.sha256((FIXTURE.parent.parent/name).read_bytes()).hexdigest()!=sha:raise ValueError('Native growth provenance changed')
    return fixture
